import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { color, texture, uv } from 'three/tsl';

export function createNode(config, ctx) {
  const { Group, Color } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);

  // 1. Stage / Backdrop Plane (~7x6 units at z=-2.5) to satisfy "STAGE, never void"
  // It carries a beautiful engineered vertical gradient utilizing the design palette.
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // Create gradient node using TSL
  const vUv = uv();
  const gradientNode = color(inkColor).mix(color(surfaceColor), vUv.y);
  // Add a very subtle horizontal accent glow on the bottom edge
  const accentGlow = color(accentColor).mul(vUv.y.oneMinus().pow(4).mul(0.15));
  backdropMat.colorNode = gradientNode.add(accentGlow);
  backdropMat.depthWrite = false;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  group.add(backdropMesh);

  // 2. Feature Card 3 (Primary Object)
  // Dimensions calibrated to fit gracefully within the hub frame layout
  const cardWidth = 2.2;
  const cardHeight = 1.4;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial();

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      // Blends the brushed metal texture with surface/ink colors for an engineered, industrial feel
      const texNode = texture(tex);
      const blendedColor = color(surfaceColor).mix(color(inkColor), 0.3).mul(texNode);
      // Subtle red accent line at the bottom of the card texture
      const edgeHighlight = color(accentColor).mul(vUv.y.oneMinus().pow(32).mul(0.4));
      cardMat.colorNode = blendedColor.add(edgeHighlight);
      cardMat.needsUpdate = true;
    });
  } else {
    // Elegant fallback gradient if asset loading is deferred
    cardMat.colorNode = color(surfaceColor).mix(color(inkColor), vUv.y);
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  // Place the mesh locally; the global parent adapter will position the group wrapper.
  group.add(cardMesh);

  // Decorate with structured text inside the card boundaries to satisfy Nova Atelier design vocabulary
  const capText = ctx.fontAtlas.createText('ENGINEERING SPEC 03', {
    fontSize: 0.07,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 1.2
  });
  capText.position.set(-cardWidth / 2 + 0.15, cardHeight / 2 - 0.2, 0.01);
  group.add(capText);

  const titleText = ctx.fontAtlas.createText('CHRONOGRAPH ATELIER', {
    fontSize: 0.12,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-cardWidth / 2 + 0.15, cardHeight / 2 - 0.45, 0.01);
  group.add(titleText);

  const descText = ctx.fontAtlas.createText('Calibrated mechanical tolerances dynamic platform monitoring system.', {
    fontSize: 0.075,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 500
  });
  descText.position.set(-cardWidth / 2 + 0.15, -0.1, 0.01);
  group.add(descText);

  // Metadata block at the bottom
  const metaText = ctx.fontAtlas.createText('SYSTEM STATUS: NOMINAL // 60Hz', {
    fontSize: 0.06,
    color: colors.paper,
    align: 'left'
  });
  metaText.position.set(-cardWidth / 2 + 0.15, -cardHeight / 2 + 0.2, 0.01);
  group.add(metaText);

  // Required cleanup interface
  group.userData = {
    cleanup() {
      cardGeo.dispose();
      cardMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
    }
  };

  return group;
}
